#include <iostream>
using namespace std;

class Complex {
    double real, imag;
public:
    Complex(double r, double i) : real(r), imag(i) {}

    friend ostream& operator<<(ostream& os, const Complex& c) {
        os << c.real << "+" << c.imag << "i";
        return os;
    }
};

int main() {
    Complex a(3, 4), b(1, 2);
    Complex sum = a + b;
    cout << "Sum: " << sum << endl;
    return 0;
}
